(4931362, 717660, 53147, '<td valign="top">Possibly taken for the brown? Doesnt seem like any aspect of the image is overexposed.</td>', 'Possibly taken for the brown? Doesnt seem like any aspect of the image is overexposed.', '2008-09-03 14:04:50.000000', NULL, 1),
(4931369, 717506, 57229, '<td valign="top">First glance - nothing. Second glance - something. And it goes on getting better. This is pastel shaded porcelain of the highest quality - well framed, too. Colour me impressed (but with a soft brush and a dexterous hand).</td>', 'First glance - nothing. Second glance - something. And it goes on getting better. This is pastel shaded porcelain of the highest quality - well framed, too. Colour me impressed (but with a soft brush and a dexterous hand).', '2008-09-03 14:07:21.000000', NULL, 1),
(4931372, 716333, 53147, '<td valign="top">Meets the challenge for sure, but the overexposure is more of a detriment than a benefit. This just feels like a poorly done snapshot.</td>', 'Meets the challenge for sure, but the overexposure is more of a detriment than a benefit. This just feels like a poorly done snapshot.', '2008-09-03 14:08:18.000000', NULL, 1),
(4931378, 715121, 53147, '<td valign="top">This just doesnt appeal to me. The overexposure is not a benefit to the image.</td>', 'This just doesnt appeal to me. The overexposure is not a benefit to the image.', '2008-09-03 14:09:20.000000', NULL, 1),
(4931382, 717385, 53147, '<td valign="top">Had this been full size the impact of the overexposure could probably be appreciate more. But considering its almost a 1/3 of what is allowed its just tough to get a good impression of the image.</td>', 'Had this been full size the impact of the overexposure could probably be appreciate more. But considering its almost a 1/3 of what is allowed its just tough to get a good impression of the image.', '2008-09-03 14:10:05.000000', NULL, 1),
(4931384, 717539, 53147, '<td valign="top">Overexposed - yes. Overexposed to the benefit of the image - not really. It just feels like the blown area is just blown, with no real purpose to make the image a more powerful image.</td>', 'Overexposed - yes. Overexposed to the benefit of the image - not really. It just feels like the blown area is just blown, with no real purpose to make the image a more powerful image.', '2008-09-03 14:11:27.000000', NULL, 1),
(4931385, 717354, 53147, '<td valign="top">I dont really equate long exposure with overexposure. This to me is just a properly exposed image considering the light.</td>', 'I dont really equate long exposure with overexposure. This to me is just a properly exposed image considering the light.', '2008-09-03 14:11:59.000000', NULL, 1),
(4931386, 717680, 57229, '<td valign="top">Yepp - this is the blowout. It''s a little hard to say what overexposure bring to the shot. Maybe some more contrast in the harder lines might help it as an abstract, along with making some more out of the complementary soft shape at the top. I think it''s what we''d call a good effort.</td>', 'Yepp - this is the blowout. It''s a little hard to say what overexposure bring to the shot. Maybe some more contrast in the harder lines might help it as an abstract, along with making some more out of the complementary soft shape at the top. I think it''s what we''d call a good effort.', '2008-09-03 14:12:14.000000', NULL, 1),
(4931389, 717385, 57229, '<td valign="top">For a bigger picture? It''s not really overexposed, either... Nice shot though.</td>', 'For a bigger picture? It''s not really overexposed, either... Nice shot though.', '2008-09-03 14:13:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4931391, 717049, 53147, '<td valign="top">Overexposed - yes. I think that some different editing though could have allowed this image to have a stronger impact. I do like blurry images so thats not an issue for me. Had you bumped the blacks up and maybe saturated the other colors a bit more this could have been a cool artistic piece. Could have had more pop. Overexposed doesnt mean that everything has to be lighter.</td>', 'Overexposed - yes. I think that some different editing though could have allowed this image to have a stronger impact. I do like blurry images so thats not an issue for me. Had you bumped the blacks up and maybe saturated the other colors a bit more this could have been a cool artistic piece. Could have had more pop. Overexposed doesnt mean that everything has to be lighter.', '2008-09-03 14:14:04.000000', NULL, 1),
(4931394, 716642, 57229, '<td valign="top">Pity about the jogging thingy, but the face idea is good and I think you''ve done it pretty well. The more-or-less correctly exposed item of clothing does distract though.</td>', 'Pity about the jogging thingy, but the face idea is good and I think you''ve done it pretty well. The more-or-less correctly exposed item of clothing does distract though.', '2008-09-03 14:15:27.000000', NULL, 1),
(4931398, 717335, 57229, '<td valign="top">It''s overexposed, but I think it would be better if it wasn''t...</td>', 'It''s overexposed, but I think it would be better if it wasn''t...', '2008-09-03 14:16:14.000000', NULL, 1),
(4931399, 717611, 53147, '<td valign="top">This doesnt really fit my concept of the challenge. There isnt really anything overexposed in the image.</td>', 'This doesnt really fit my concept of the challenge. There isnt really anything overexposed in the image.', '2008-09-03 14:16:18.000000', NULL, 1),
(4931400, 717518, 53147, '<td valign="top">uhmmm - not sure what to say with this one. Maybe that I just dont get it?</td>', 'uhmmm - not sure what to say with this one. Maybe that I just dont get it?', '2008-09-03 14:16:45.000000', NULL, 1),
(4931402, 717667, 57229, '<td valign="top">Looks more overprocessed than overexposed.</td>', 'Looks more overprocessed than overexposed.', '2008-09-03 14:17:01.000000', NULL, 1),
(4931403, 717270, 53147, '<td valign="top">Pleasing relaxing image, but the overexposure aspect of it isnt really a strong part.</td>', 'Pleasing relaxing image, but the overexposure aspect of it isnt really a strong part.', '2008-09-03 14:17:22.000000', NULL, 1),
(4931405, 717093, 53147, '<td valign="top">While this may meet the challenge, the end product I dont find pleasing. Colors are a bit too funky, overall image doesnt grab me.</td>', 'While this may meet the challenge, the end product I dont find pleasing. Colors are a bit too funky, overall image doesnt grab me.', '2008-09-03 14:18:31.000000', NULL, 1),
(4931408, 717711, 57229, '<td valign="top">Cute shot. Sorry, that doesn''t tell you much does it? The use of light and the effect of the overexposure - all very nicely answering to the challenge :)- are good but it doesn''t make that extra shout to me. It''s a nice portrait but I would think there''s room for a fair bit of ambition in this challenge.</td>', 'Cute shot. Sorry, that doesn''t tell you much does it? The use of light and the effect of the overexposure - all very nicely answering to the challenge :)- are good but it doesn''t make that extra shout to me. It''s a nice portrait but I would think there''s room for a fair bit of ambition in this challenge.', '2008-09-03 14:20:40.000000', NULL, 1),
(4931411, 717675, 57229, '<td valign="top">Doesn''t look remotely overexposed to me.</td>', 'Doesn''t look remotely overexposed to me.', '2008-09-03 14:21:08.000000', NULL, 1),
(4931413, 717566, 53147, '<td valign="top">While this does meet the challenge the image itself is lacking impact. It just doesnt grab me.</td>', 'While this does meet the challenge the image itself is lacking impact. It just doesnt grab me.', '2008-09-03 14:22:31.000000', NULL, 1),
(4931414, 717554, 57229, '<td valign="top">I''m not about to join the fan club, but I think what you''ve done here, you''ve done right. If ever there were seriously specific challenge guidelines, this might get ten for technical :)</td>', 'I''m not about to join the fan club, but I think what you''ve done here, you''ve done right. If ever there were seriously specific challenge guidelines, this might get ten for technical :)', '2008-09-03 14:23:21.000000', NULL, 1),
(4931415, 717332, 53147, '<td valign="top">I havent said this yet - but maybe a bit too overexposed. That or maybe a darkening of the blues/blacks to give it a bit more pop would be nice. That siad I am going to bump this up one as I think I may have been ab it harsh on this one in my first vote around.</td>', 'I havent said this yet - but maybe a bit too overexposed. That or maybe a darkening of the blues/blacks to give it a bit more pop would be nice. That siad I am going to bump this up one as I think I may have been ab it harsh on this one in my first vote around.', '2008-09-03 14:23:47.000000', NULL, 1),
(4931419, 717421, 57229, '<td valign="top">While the face is overexposed, it''s made into background by this composition. Ergo, not overexposure.</td>', 'While the face is overexposed, it''s made into background by this composition. Ergo, not overexposure.', '2008-09-03 14:24:37.000000', NULL, 1),
(4931424, 717600, 53147, '<td valign="top">The color work on this just has such an odd feel. It makes it seem like the girl is cut and pasted onto the backdrop. I just dont find it to be a pleasing image.</td>', 'The color work on this just has such an odd feel. It makes it seem like the girl is cut and pasted onto the backdrop. I just dont find it to be a pleasing image.', '2008-09-03 14:25:43.000000', NULL, 1),
(4931426, 717103, 53147, '<td valign="top">I can see that aspects are overexposed, but I dont see it as being a benefit to the image. I dont find it an appealing image.</td>', 'I can see that aspects are overexposed, but I dont see it as being a benefit to the image. I dont find it an appealing image.', '2008-09-03 14:26:25.000000', NULL, 1),
(4931428, 717603, 43774, '<td valign="top">Overexposed nicely to kep detail and colour in the flowers. Not so sure I like the centered composition but it is a very pretty photo.</td>', 'Overexposed nicely to kep detail and colour in the flowers. Not so sure I like the centered composition but it is a very pretty photo.', '2008-09-03 14:27:05.000000', NULL, 1),
(4931429, 717554, 43774, '<td valign="top">I like her pose and the composition, good job.</td>', 'I like her pose and the composition, good job.', '2008-09-03 14:27:20.000000', NULL, 1),
(4931431, 717686, 43774, '<td valign="top">Oh very nice, good detail.</td>', 'Oh very nice, good detail.', '2008-09-03 14:27:38.000000', NULL, 1),
(4931432, 717201, 43774, '<td valign="top">Yes indeed!! A lovely photo</td>', 'Yes indeed!! A lovely photo', '2008-09-03 14:27:50.000000', NULL, 1),
(4931434, 717688, 97954, '<td valign="top">This is a really nice photos - I really like it just didn''t fit the overexposure as much as others did.</td>', 'This is a really nice photos - I really like it just didn''t fit the overexposure as much as others did.', '2008-09-03 14:27:55.000000', NULL, 1),
(4931435, 714829, 43774, '<td valign="top">He''s quite handsome, I like his gaze.</td>', 'He''s quite handsome, I like his gaze.', '2008-09-03 14:28:07.000000', NULL, 1),
(4931436, 717226, 43774, '<td valign="top">Good detail in the eyes, nice work.</td>', 'Good detail in the eyes, nice work.', '2008-09-03 14:28:29.000000', NULL, 1),
(4931437, 717146, 53147, '<td valign="top">Very cool capture. But the small area that is overexposed is such a small and incidental aspect of the image that it doesnt really have an impact on the picture. The man, the fork and hay, the hat, the tobacco - those are my primary interests in the image. I actually wish the window wasnt there and it was just more slots between the boards. But again - a very cool capture - just not for this challenge.</td>', 'Very cool capture. But the small area that is overexposed is such a small and incidental aspect of the image that it doesnt really have an impact on the picture. The man, the fork and hay, the hat, the tobacco - those are my primary interests in the image. I actually wish the window wasnt there and it was just more slots between the boards. But again - a very cool capture - just not for this challenge.', '2008-09-03 14:28:44.000000', NULL, 1),
(4931442, 717090, 57229, '<td valign="top">They do, don''t they? Lovely colours - nice take on the challenge...</td>', 'They do, don''t they? Lovely colours - nice take on the challenge...', '2008-09-03 14:31:52.000000', NULL, 1),
(4931443, 717592, 53147, '<td valign="top">I guess there are areas that are overexposed, but the image itself just falls flat for me.</td>', 'I guess there are areas that are overexposed, but the image itself just falls flat for me.', '2008-09-03 14:32:01.000000', NULL, 1),
(4931446, 717656, 57229, '<td valign="top">Nice. Sort of softens out, but it would do that, wouldn''t it?</td>', 'Nice. Sort of softens out, but it would do that, wouldn''t it?', '2008-09-03 14:32:38.000000', NULL, 1),
(4931449, 715536, 97954, '<td valign="top">I can''t decide if this fits the category of not but this is really nice - I love how the rocks (?) lead you into the photo.</td>', 'I can''t decide if this fits the category of not but this is really nice - I love how the rocks (?) lead you into the photo.', '2008-09-03 14:32:52.000000', NULL, 1),
(4931450, 715067, 53147, '<td valign="top">Hmmm - impact is what I find missing in this image. I can see that there is some overexposure, but the image itself just feels a bit flat to me and without purpose.</td>', 'Hmmm - impact is what I find missing in this image. I can see that there is some overexposure, but the image itself just feels a bit flat to me and without purpose.', '2008-09-03 14:33:57.000000', NULL, 1),
(4931453, 715103, 53147, '<td valign="top">It is overexposed but it doesnt seem to be that way for any benefit of the image as a whole other than to meet the challenge.</td>', 'It is overexposed but it doesnt seem to be that way for any benefit of the image as a whole other than to meet the challenge.', '2008-09-03 14:34:32.000000', NULL, 1),
(4931455, 717240, 53147, '<td valign="top">Not digging the border at all. But on second look at this I think I may have been a bit harsh on the first vote around. This does have a somewhat pleasing painting like effect to it. Bumping up 1.</td>', 'Not digging the border at all. But on second look at this I think I may have been a bit harsh on the first vote around. This does have a somewhat pleasing painting like effect to it. Bumping up 1.', '2008-09-03 14:35:26.000000', NULL, 1),
(4931459, 715202, 53147, '<td valign="top">Quirky image. I dont think the overexposure is a real benefit to this image. I am not sure how you pulled off a total desat on the character on the right within basic rules either.</td>', 'Quirky image. I dont think the overexposure is a real benefit to this image. I am not sure how you pulled off a total desat on the character on the right within basic rules either.', '2008-09-03 14:38:04.000000', NULL, 1),
(4931461, 717175, 53147, '<td valign="top">Cool colors and an interesting painting like effect. I may have been abit harsh on the first vote around. Bumping up 1.</td>', 'Cool colors and an interesting painting like effect. I may have been abit harsh on the first vote around. Bumping up 1.', '2008-09-03 14:38:44.000000', NULL, 1),
(4931463, 717650, 53147, '<td valign="top">Surely overexposed, but not to the benefit of the image IMO.</td>', 'Surely overexposed, but not to the benefit of the image IMO.', '2008-09-03 14:39:05.000000', NULL, 1),
(4931466, 717680, 61679, '<td valign="top">Nicely done.  I like the composition and the over exposed area works well with the subject. 9</td>', 'Nicely done.  I like the composition and the over exposed area works well with the subject. 9', '2008-09-03 14:40:34.000000', NULL, 1),
(4931467, 717710, 53147, '<td valign="top">The background may be overexposed but it doesnt make the image any stronger. The bird looks great and is exposed perfectly. I wish the back wasnt. But then I probably would have voted it lower for really not fitting the challenge, but it would have been a stronger picture all around - challenge not considered.</td>', 'The background may be overexposed but it doesnt make the image any stronger. The bird looks great and is exposed perfectly. I wish the back wasnt. But then I probably would have voted it lower for really not fitting the challenge, but it would have been a stronger picture all around - challenge not considered.', '2008-09-03 14:40:37.000000', NULL, 1),
(4931475, 717433, 53147, '<td valign="top">Probably not overexposed enough to bring in the big votes, but man I dig this picture. That is one heck of a look you caught on that cats puss.</td>', 'Probably not overexposed enough to bring in the big votes, but man I dig this picture. That is one heck of a look you caught on that cats puss.', '2008-09-03 14:42:39.000000', NULL, 1),
(4931478, 717565, 97954, '<td valign="top">Wow - I can''t believe those eyes! Great capture!</td>', 'Wow - I can''t believe those eyes! Great capture!', '2008-09-03 14:42:54.000000', NULL, 1),
(4931480, 716359, 53147, '<td valign="top">Beautiful piece of art you have here. I hope to see this front page. Perfect for the challenge. Bumping up 1.</td>', 'Beautiful piece of art you have here. I hope to see this front page. Perfect for the challenge. Bumping up 1.', '2008-09-03 14:43:15.000000', NULL, 1),
(4931482, 717474, 53147, '<td valign="top">Lovely image. Works perfectly in the challenge. Just lovely. Bumping up 1.</td>', 'Lovely image. Works perfectly in the challenge. Just lovely. Bumping up 1.', '2008-09-03 14:43:44.000000', NULL, 1),
(4931483, 717253, 53147, '<td valign="top">Beautiful image. Not really sure if its truly overexposed, but the high key effect works for me in this challenge.</td>', 'Beautiful image. Not really sure if its truly overexposed, but the high key effect works for me in this challenge.', '2008-09-03 14:44:37.000000', NULL, 1),
(4931487, 717654, 53147, '<td valign="top">With Aidan starting kindergarten last week this image hits home. Great colors and detail. The overexposure is a great element in the image.</td>', 'With Aidan starting kindergarten last week this image hits home. Great colors and detail. The overexposure is a great element in the image.', '2008-09-03 14:45:23.000000', NULL, 1),
(4931488, 716347, 53147, '<td valign="top">Dang that just looks cool.</td>', 'Dang that just looks cool.', '2008-09-03 14:45:37.000000', NULL, 1),
(4931492, 716639, 53147, '<td valign="top">Very cool shot. This works for me on several levels. Bumping up 1.</td>', 'Very cool shot. This works for me on several levels. Bumping up 1.', '2008-09-03 14:46:05.000000', NULL, 1),
(4931493, 717216, 53147, '<td valign="top">For some reason this image grabs me. Just has a cool feel to it and I like the impact of the overexposure on it.</td>', 'For some reason this image grabs me. Just has a cool feel to it and I like the impact of the overexposure on it.', '2008-09-03 14:46:41.000000', NULL, 1),
(4931494, 717417, 61679, '<td valign="top">Nice take on the challenge.  I would have liked a deeper depth of focus on this image (sharper eyes) but the shallow depth also works well. 7</td>', 'Nice take on the challenge.  I would have liked a deeper depth of focus on this image (sharper eyes) but the shallow depth also works well. 7', '2008-09-03 14:47:02.000000', NULL, 1),
(4931495, 717686, 53147, '<td valign="top">Very nice. Keeping the blacks and the detail work very well with this. Probably not overexposed enough for some, but a strong image on its own.</td>', 'Very nice. Keeping the blacks and the detail work very well with this. Probably not overexposed enough for some, but a strong image on its own.', '2008-09-03 14:47:23.000000', NULL, 1),
(4931500, 717685, 61679, '<td valign="top">Nicely done.  I could easily imagine this hanging on someone''s wall. 7</td>', 'Nicely done.  I could easily imagine this hanging on someone''s wall. 7', '2008-09-03 14:47:56.000000', NULL, 1),
(4931504, 717385, 81530, '<td valign="top">Image is too small</td>', 'Image is too small', '2008-09-03 14:49:52.000000', NULL, 1),
(4931516, 717403, 61679, '<td valign="top">Nicely done.  You could have cropped a little bit off the right side to move the girl off center to strengthen the composition. 7</td>', 'Nicely done.  You could have cropped a little bit off the right side to move the girl off center to strengthen the composition. 7', '2008-09-03 14:52:07.000000', NULL, 1),
(4931521, 717201, 53147, '<td valign="top">This little cutie looks awfully familiar. but she looks far from awful. Beautiful image. For the challenge I think it could have been pushed a bit brighter in editing to really nail the challenge. But - this is a keeper for sure. Print worthy and one I would be proud to have of my daughter.<br/> <br/>Isabella?</td>', 'This little cutie looks awfully familiar. but she looks far from awful. Beautiful image. For the challenge I think it could have been pushed a bit brighter in editing to really nail the challenge. But - this is a keeper for sure. Print worthy and one I would be proud to have of my daughter. Isabella?', '2008-09-03 14:53:38.000000', NULL, 1),
(4931524, 717738, 53147, '<td valign="top">Great look. This is the type of overexposure that I really like.</td>', 'Great look. This is the type of overexposure that I really like.', '2008-09-03 14:54:09.000000', NULL, 1),
(4931528, 717675, 61679, '<td valign="top">A welcome surprise in this white background, I mean overexposed challenge. 7</td>', 'A welcome surprise in this white background, I mean overexposed challenge. 7', '2008-09-03 14:54:59.000000', NULL, 1),
(4931529, 715557, 53147, '<td valign="top">Very cool shot. Great detail. I love that the blacks are kept intact and the highlights and midtones are what are bright. I find this to be a very pleasing image.</td>', 'Very cool shot. Great detail. I love that the blacks are kept intact and the highlights and midtones are what are bright. I find this to be a very pleasing image.', '2008-09-03 14:55:12.000000', NULL, 1),
(4931534, 717685, 53147, '<td valign="top">Very cool shot. Not really sure if its going to be overexposed enough to keep the dnmcs away as the ducks seem to be in perfect exposure. Strong image none the less.</td>', 'Very cool shot. Not really sure if its going to be overexposed enough to keep the dnmcs away as the ducks seem to be in perfect exposure. Strong image none the less.', '2008-09-03 14:56:07.000000', NULL, 1),
(4931563, 717654, 61679, '<td valign="top">Nicely done.  I like the composition and the over exposed area works well with the subject. My favorite of the challenge so far. 10</td>', 'Nicely done.  I like the composition and the over exposed area works well with the subject. My favorite of the challenge so far. 10', '2008-09-03 15:04:13.000000', NULL, 1),
(4931580, 717560, 93927, '<td valign="top">the light form is dirty. not quite a 45, not quite a split.</td>', 'the light form is dirty. not quite a 45, not quite a split.', '2008-09-03 15:11:11.000000', NULL, 1),
(4931587, 717587, 61679, '<td valign="top">A welcome surprise in this white background, I mean overexposed challenge.  Hope the DNMC crowd is being kind. 9</td>', 'A welcome surprise in this white background, I mean overexposed challenge.  Hope the DNMC crowd is being kind. 9', '2008-09-03 15:13:02.000000', NULL, 1),
(4931590, 716246, 61679, '<td valign="top">Your overexposure adds to the composition of this image.  Hope you don''t get hammered by the DNMC crowd. 8  Back to bump 9.</td>', 'Your overexposure adds to the composition of this image.  Hope you don''t get hammered by the DNMC crowd. 8  Back to bump 9.', '2008-09-03 15:13:17.000000', NULL, 1),
(4931597, 717565, 44741, '<td valign="top">My favorite! Great job.</td>', 'My favorite! Great job.', '2008-09-03 15:14:38.000000', NULL, 1),
(4931643, 715536, 26001, '<td valign="top">This one has "front page" written all over 10</td>', 'This one has "front page" written all over 10', '2008-09-03 15:30:40.000000', NULL, 1),
(4931668, 716833, 98034, '<td valign="top">Very nice composition</td>', 'Very nice composition', '2008-09-03 15:43:25.000000', NULL, 1),
(4931696, 715202, 43774, '<td valign="top">Not sure I like the selective desaturation and the figures in front look slightly out of focus. But I like the look of the rose petals.</td>', 'Not sure I like the selective desaturation and the figures in front look slightly out of focus. But I like the look of the rose petals.', '2008-09-03 15:55:52.000000', NULL, 1),
(4931699, 716347, 43774, '<td valign="top">Nice composition.....did you use a bit too much neat image? Or perhaps it''s just a soft focus I am seeing.</td>', 'Nice composition.....did you use a bit too much neat image? Or perhaps it''s just a soft focus I am seeing.', '2008-09-03 15:56:26.000000', NULL, 1),
(4931700, 717697, 57229, '<td valign="top">Quite nicely done. Don''t like the frame. I''m wondering if more contrast, or maybe a fetching up of the blacks in the midtones might make more of a graphic out of it. (I do think that would be the way to go). Still, it''s basic editing and you''ve made a fist of it.</td>', 'Quite nicely done. Don''t like the frame. I''m wondering if more contrast, or maybe a fetching up of the blacks in the midtones might make more of a graphic out of it. (I do think that would be the way to go). Still, it''s basic editing and you''ve made a fist of it.', '2008-09-03 15:56:36.000000', NULL, 1),
(4931701, 717378, 43774, '<td valign="top">I like the composition a lot.</td>', 'I like the composition a lot.', '2008-09-03 15:56:40.000000', NULL, 1),
(4931702, 717433, 43774, '<td valign="top">Awesome perspective, what a glare the cat has!</td>', 'Awesome perspective, what a glare the cat has!', '2008-09-03 15:56:55.000000', NULL, 1),
(4931706, 715429, 57229, '<td valign="top">Cast away and blown out. Simple and effective.</td>', 'Cast away and blown out. Simple and effective.', '2008-09-03 15:57:13.000000', NULL, 1),
(4931707, 717654, 43774, '<td valign="top">Good job....what wonders lurk in that brightness?</td>', 'Good job....what wonders lurk in that brightness?', '2008-09-03 15:57:13.000000', NULL, 1),
(4931710, 717683, 43774, '<td valign="top">Funny title. How did that peson get there on top of the fountain? Cool, however you did it.</td>', 'Funny title. How did that peson get there on top of the fountain? Cool, however you did it.', '2008-09-03 15:57:48.000000', NULL, 1),
