(4935066, 717201, 30454, '<td valign="top">Yes, she is adorable. Lovely portrait, I really like this. The only reason this may score low is due to DNMC police.</td>', 'Yes, she is adorable. Lovely portrait, I really like this. The only reason this may score low is due to DNMC police.', '2008-09-04 21:01:14.000000', NULL, 1),
(4935067, 717362, 30454, '<td valign="top">Nice IR processing here. I really like this one. Hope this one will score better.</td>', 'Nice IR processing here. I really like this one. Hope this one will score better.', '2008-09-04 21:02:05.000000', NULL, 1),
(4935068, 714829, 30454, '<td valign="top">Nice portrait. Good composition, great tones here. I hope this to score well.</td>', 'Nice portrait. Good composition, great tones here. I hope this to score well.', '2008-09-04 21:03:13.000000', NULL, 1),
(4935069, 717226, 30454, '<td valign="top">Very nice PP here. I like the the sharpness and colors in the eye. The blue colors gives a feeling of deep blue sea or the earth.</td>', 'Very nice PP here. I like the the sharpness and colors in the eye. The blue colors gives a feeling of deep blue sea or the earth.', '2008-09-04 21:04:30.000000', NULL, 1),
(4935072, 717685, 30454, '<td valign="top">Cool photo, nice use of over exposure here. Just to nit pick, faces of couple of ducks is blended with body of other duck. Also, I am not a fan od border here. Doen''t take away much from the picture, just the personal preference, good luck.</td>', 'Cool photo, nice use of over exposure here. Just to nit pick, faces of couple of ducks is blended with body of other duck. Also, I am not a fan od border here. Doen''t take away much from the picture, just the personal preference, good luck.', '2008-09-04 21:07:26.000000', NULL, 1),
(4935076, 717686, 30454, '<td valign="top">Great composition, focus right on spot. I like the fact that overexposure is not implemented forcefully. Just to nit pick, I don''t like border that much here. This should score well, good luck.</td>', 'Great composition, focus right on spot. I like the fact that overexposure is not implemented forcefully. Just to nit pick, I don''t like border that much here. This should score well, good luck.', '2008-09-04 21:09:18.000000', NULL, 1),
(4935077, 716482, 30454, '<td valign="top">Nice picture here. The focus is too soft for my preference. More than over expossed, to me this it looks more brightness. The contrast is missing here. 7</td>', 'Nice picture here. The focus is too soft for my preference. More than over expossed, to me this it looks more brightness. The contrast is missing here. 7', '2008-09-04 21:12:53.000000', NULL, 1),
(4935088, 717433, 82707, '<td valign="top">...with attitude!  Great image and the overexposure enhances the subject beautifully.</td>', '...with attitude!  Great image and the overexposure enhances the subject beautifully.', '2008-09-04 21:26:32.000000', NULL, 1),
(4935134, 715536, 56792, '<td valign="top">Nice , this is what i had in my mind , but could nt go to the location. If i were you , i would  have lowered the elevation of shot , but that is my opinion.</td>', 'Nice , this is what i had in my mind , but could nt go to the location. If i were you , i would  have lowered the elevation of shot , but that is my opinion.', '2008-09-04 21:50:24.000000', NULL, 1),
