(4940738, 717482, 76335, '<td valign="top">A bit harsh in the processing, I think. Orange is never a popular color, but it does kind of work here.</td>', 'A bit harsh in the processing, I think. Orange is never a popular color, but it does kind of work here.', '2008-09-07 22:49:37.000000', NULL, 1),
(4940739, 717420, 76335, '<td valign="top">Great expression and a fun shot, but the OE doesn''t add much in my opinion.</td>', 'Great expression and a fun shot, but the OE doesn''t add much in my opinion.', '2008-09-07 22:50:11.000000', NULL, 1),
