(4943803, 717484, 57229, '<td valign="top">Ah, the play on words. Works well here, too.</td>', 'Ah, the play on words. Works well here, too.', '2008-09-09 05:54:58.000000', NULL, 1),
(4943804, 717253, 57229, '<td valign="top">Calm, nicely done - I''d like to see just a little more texture in the white (there''s another entry that does that), but the subject is quite lovely and there''s some great sharpness on the head.</td>', 'Calm, nicely done - I''d like to see just a little more texture in the white (there''s another entry that does that), but the subject is quite lovely and there''s some great sharpness on the head.', '2008-09-09 05:57:31.000000', NULL, 1),
